-- Sincroniza la tabla productos con el catalogo_limpio/productos.sql corregido.
-- Ejecutar completo en Supabase SQL Editor.

-- 1) Asegura que codigo sea unico (necesario para el UPSERT)
DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'productos_codigo_key'
  ) THEN
    ALTER TABLE productos ADD CONSTRAINT productos_codigo_key UNIQUE (codigo);
  END IF;
END $$;

-- 2) Inserta/actualiza los 344 productos correctos (nombre y precio)
ON CONFLICT (codigo) DO UPDATE SET
  nombre = EXCLUDED.nombre,
  precio_regular = EXCLUDED.precio_regular,
  precio_oferta = EXCLUDED.precio_oferta;

-- 3) Elimina productos descontinuados (no estan en el catalogo nuevo)
